#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Trial: planning_simulator (no sensors, no renderer, no GPU): initialize the ego on the sample map (sim_start of route.json),
# set the route to the goal, engage autonomous, watch trajectory / control_cmd / velocity for DRIVE_S seconds.
# usage: planning_sim_trial.sh <route.json> [log_dir]      env: IMG (fishwait29), DRIVE_S (60)
set -u; R=${1:?route.json}; LD=${2:-$HOME/fish_traces/sim_route/psim_$(date +%H%M%S)}; mkdir -p "$LD"
IMG=${IMG:-autoware-dev-trt-a1000-fishwait29:latest}; DRIVE_S=${DRIVE_S:-60}
python3 -c "import json; a=json.load(open('$R'))['adapi']; open('$LD/init.cmd','w').write(a['initialize']); open('$LD/set_route.cmd','w').write(a['set_route_points']); open('$LD/auto.cmd','w').write(a['autonomous'])"
NAME=psim_trial_$$; docker rm -f $NAME >/dev/null 2>&1
docker run -d --name $NAME --privileged --net host -e DRIVE_S=$DRIVE_S -v "$LD":/trial "$IMG" bash -lc '
  set +u; source /opt/ros/humble/setup.bash; source /opt/autoware/setup.bash; export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp
  unset CYCLONEDDS_URI; export FISH_ENABLED=0; R2=/opt/ros/humble/bin/ros2
  ( $R2 launch autoware_launch planning_simulator.launch.xml map_path:=/root/autoware_map/sample-map-rosbag vehicle_model:=sample_vehicle sensor_model:=sample_sensor_kit rviz:=false > /trial/launch.log 2>&1 ) & LPID=$!
  for i in $(seq 1 90); do $R2 service list 2>/dev/null | grep -q /api/routing/set_route_points && break; sleep 5; done
  echo "[psim] $(date +%T) adapi up after $((i*5)) s; nodes: $($R2 node list 2>/dev/null | wc -l)" | tee -a /trial/trial.log; sleep 15
  for k in 1 2 3; do out=$(timeout 40 bash -c "$(cat /trial/init.cmd)" 2>&1 | tail -2); echo "[psim] $(date +%T) initialize: $out" | tee -a /trial/trial.log; sleep 5
    st=$(timeout 8 $R2 topic echo --once /api/localization/initialization_state 2>/dev/null | grep "^state" | head -1); echo "[psim] init state: $st" | tee -a /trial/trial.log; [[ "$st" == *"3"* ]] && break; done
  timeout 6 $R2 topic echo --once /localization/kinematic_state --no-arr 2>/dev/null | grep -A3 "position:" | head -4 | tee -a /trial/trial.log
  out=$(timeout 40 bash -c "$(cat /trial/set_route.cmd)" 2>&1 | tail -3); echo "[psim] $(date +%T) set_route_points: $out" | tee -a /trial/trial.log; sleep 5
  st=$(timeout 8 $R2 topic echo --once /api/routing/state 2>/dev/null | grep "^state" | head -1); echo "[psim] routing state: $st" | tee -a /trial/trial.log
  for k in 1 2 3; do out=$(timeout 30 bash -c "$(cat /trial/auto.cmd)" 2>&1 | tail -2); echo "[psim] $(date +%T) change_to_autonomous: $out" | tee -a /trial/trial.log; echo "$out" | grep -q "success=True" && break; sleep 8; done
  T0=$(date +%s); while [ $(( $(date +%s) - T0 )) -lt $DRIVE_S ]; do
    v=$(timeout 5 $R2 topic echo --once /vehicle/status/velocity_status 2>/dev/null | grep longitudinal_velocity | head -1)
    echo "[psim] $(date +%T) $v | traj hz: $(timeout 6 $R2 topic hz /planning/scenario_planning/trajectory 2>&1 | grep -m1 average) | control_cmd hz: $(timeout 6 $R2 topic hz /control/command/control_cmd 2>&1 | grep -m1 average) | mode: $(timeout 5 $R2 topic echo --once /api/operation_mode/state 2>/dev/null | grep -E "^mode" | head -1)" | tee -a /trial/trial.log
  done
  timeout 6 $R2 topic echo --once /localization/kinematic_state --no-arr 2>/dev/null | grep -A3 "position:" | head -4 | tee -a /trial/trial.log
  kill -INT $LPID 2>/dev/null; sleep 10; pkill -INT -f component_container 2>/dev/null; sleep 5; echo "[psim] TRIAL DONE" | tee -a /trial/trial.log
' >/dev/null || { echo "cannot start container"; exit 2; }
echo "planning_simulator trial $NAME started; log $LD/trial.log"
